/**
 * Glossary storage.
 *
 * - Built-in collections: src/seed/glossary/*.json (generated by scripts/glossary/*.py).
 * - User entries/edits: <data-dir>/glossary/<entry-id>.json.
 *   - New id → a custom entry (stored in full).
 *   - Built-in id → only the fields you changed (e.g. just `notes`) are stored and merged over the
 *     shipped entry, so later improvements to untouched built-in fields still reach you.
 */
import { storage } from "../../lib/storage";

export interface CodeExample { language: string; code: string }
export interface WildNote { framework: string; note: string; url: string }
export interface Quote { text: string; source: string; url: string }
export interface Link { label: string; url: string }

export interface GlossaryEntry {
  id: string;
  title: string;
  category: string;
  group?: string;
  summary: string;
  quote?: Quote;
  problem?: string;
  solution?: string;
  whenToUse?: string[];
  pros?: string[];
  cons?: string[];
  signs?: string[];
  examples?: CodeExample[];
  inTheWild?: WildNote[];
  related?: string[];
  links?: Link[];
  /** Your own Markdown notes. */
  notes?: string;
}

export interface Collection {
  id: string;
  title: string;
  description: string;
  groups: string[];
  source?: { name: string; url: string };
  entries: GlossaryEntry[];
}

export type Origin = "builtin" | "modified" | "custom";
export interface EntryRecord { entry: GlossaryEntry; origin: Origin }

const DIR = "glossary";
const ORDER = ["design-patterns", "architecture", "principles", "code-smells", "refactoring-techniques"];

const modules = import.meta.glob<Collection>("../../seed/glossary/*.json", { eager: true, import: "default" });
export const COLLECTIONS: Collection[] = Object.values(modules).sort(
  (a, b) => ORDER.indexOf(a.id) - ORDER.indexOf(b.id),
);
// An entry's category is always its collection's title, so the two can't drift apart.
const BUILTIN = new Map(
  COLLECTIONS.flatMap((c) => c.entries.map((e) => [e.id, { ...e, category: c.title }] as const)),
);

export const CUSTOM_CATEGORY = "My Entries";

export function slugify(s: string): string {
  return s.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "entry";
}

export async function loadEntries(): Promise<EntryRecord[]> {
  const user = new Map<string, GlossaryEntry>();
  for (const f of await storage.list(DIR)) {
    try {
      const e = await storage.read<GlossaryEntry>(`${DIR}/${f}`);
      // Built-in overrides may be partial (just `notes`); custom entries need a title.
      if (e?.id && (BUILTIN.has(e.id) || e.title)) user.set(e.id, e);
    } catch (err) {
      console.warn(`Skipping invalid glossary entry ${f}`, err);
    }
  }
  const out: EntryRecord[] = [];
  for (const [id, e] of BUILTIN) {
    const patch = user.get(id);
    out.push(patch ? { entry: { ...e, ...patch, id, category: e.category }, origin: "modified" } : { entry: e, origin: "builtin" });
  }
  for (const [id, e] of user) if (!BUILTIN.has(id)) out.push({ entry: e, origin: "custom" });
  return out;
}

/** Empty strings/lists count as "not set" so the editor's normalisation isn't seen as a change. */
const unset = (v: unknown) => (v === undefined || v === "" || (Array.isArray(v) && v.length === 0) ? null : v);

/** Saves a custom entry in full, or only the changed fields of a built-in one. */
export async function saveEntry(e: GlossaryEntry): Promise<void> {
  const base = BUILTIN.get(e.id);
  if (!base) return storage.write(`${DIR}/${e.id}.json`, e);

  const patch: Partial<GlossaryEntry> = {};
  for (const key of Object.keys({ ...base, ...e }) as (keyof GlossaryEntry)[]) {
    if (key === "id" || key === "category") continue;
    if (JSON.stringify(unset(e[key])) !== JSON.stringify(unset(base[key]))) {
      (patch as Record<string, unknown>)[key] = e[key];
    }
  }
  // Identical to the shipped entry → no override file at all.
  if (Object.keys(patch).length === 0) return storage.remove(`${DIR}/${e.id}.json`);
  return storage.write(`${DIR}/${e.id}.json`, { id: e.id, ...patch });
}

export const deleteEntry = (id: string) => storage.remove(`${DIR}/${id}.json`);
export const isBuiltin = (id: string) => BUILTIN.has(id);

export function uniqueId(title: string, taken: Set<string>): string {
  let id = slugify(title);
  for (let n = 2; taken.has(id); n++) id = `${slugify(title)}-${n}`;
  return id;
}

/** Categories in display order: built-in collections first, then any custom ones. */
export function categoriesOf(records: EntryRecord[]): { title: string; count: number; collection?: Collection }[] {
  const counts = new Map<string, number>();
  for (const { entry } of records) counts.set(entry.category, (counts.get(entry.category) ?? 0) + 1);
  const builtin = COLLECTIONS.map((c) => ({ title: c.title, count: counts.get(c.title) ?? 0, collection: c }));
  const extra = [...counts.keys()].filter((t) => !COLLECTIONS.some((c) => c.title === t)).sort()
    .map((t) => ({ title: t, count: counts.get(t)! }));
  return [...builtin, ...extra];
}
